def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = remaining / (item + 1e-8)
    return np.where(remaining < 0, -np.inf, 1.0 / (1.0 + np.abs(ratio - 0.5)))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, remaining)
